def sort_even(l: list):
    even_indices = sorted(l[i] for i in range(len(l)) if i % 2 == 0)
    result = l[:]

    for idx, value in enumerate(result):
        if idx % 2 == 0:
            result[idx] = even_indices.pop(0)

    return result

